      "path": "packages/helmd/src/tools/caseflow.ts",
      "content": "// Case lifecycle tools: begin_case / case_status / record_finding / save_evidence /\n// end_case — every one of them reads or writes the session's active case.\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport { existsSync } from 'node:fs'\nimport { resolve } from 'node:path'\nimport {\n  bindCase, getCase, unbindCase, createCaseDir, loadCaseMd, closeCase,\n  validateEvidenceIds, recordFinding, updateFinding, saveEvidence, countEvidence,\n  severityCounts, findingStatusCounts,\n  casesRoot, findOpenCaseOnDisk, loadCaseInfoFromDisk, auditCasesRoot,\n  listLooseFilesInCase,\n  recordHypothesis, updateHypothesis, loadHypotheses, getOpenHypothesisCount,\n  listEvidence, loadFindings,\n  FINDING_SEVERITIES, FINDING_STATUSES, FINDING_CONFIDENCES,\n  type FindingSeverity, type FindingStatus, type FindingConfidence,\n} from '../case.js'\nimport { getLevel } from '../mode.js'\nimport { renderAdvisoryStats } from '../advisory.js'\nimport { getStreamInterceptionStats } from '../llm-stream-hook.js'\nimport { renderAutonomyPacket } from '../autonomy.js'\nimport { loadSettings } from '../settings.js'\nimport { createTicket } from '../team.js'\nimport { sessionEvents, toolCalls } from '../session-log.js'\n\ninterface ExecLike {\n  agent?: {\n    id?: string\n    cwd?: string\n    workspace?: string\n    session?: {\n      header?: {\n        cwd?: string\n      }\n    }\n  }\n}\n\nfunction resolveWorkspaceRoot(root?: string, exec?: ExecLike): string | undefined {\n  return root?.trim() || exec?.agent?.session?.header?.cwd || exec?.agent?.cwd || exec?.agent?.workspace\n}\n\nconst RULES = [\n  '1. Built-in tools first; missing capability → use shell (gh/curl) to find and install it; custom scripts LAST, only in <case>/scripts/.',\n  '2. External CLI output → save_evidence(label, ...) before citing it.',\n  '3. Parameters come from prior tool output in evidence/. Findings cite E ids via record_finding.',\n  '4. Resume after compaction → case_status(); before compaction, bring the CASE.md `## resume` block up to date.',\n  '5. A tactic failing 3 times in a row on the same target (no new evidence) → stop, record the dead end in the case, and never retry it without new evidence.',\n].join('\\n')\n\nexport function registerCaseflowTools(ctx: Context): void {\n  ctx.tools.register(defineTool({\n    name: 'begin_case',\n    description:\n      'Start a case workspace for one sample/investigation: creates <workspace>/helmd-cases/<date>-<slug>/ ' +\n      '(sample/, evidence/, scripts/, CASE.md), hashes samples as first evidence, routes the goal, and binds it to this session. ' +\n      'Call before analyzing a new sample. Pass root = the workspace directory shown in your environment when unsure.',\n    parameters: {\n      goal: { type: 'string', required: true, description: 'What this investigation must deliver.' },\n      samples: { type: 'array', items: { type: 'string' }, description: 'Absolute paths of sample files to ingest.' },\n      root: { type: 'string', description: 'Workspace root; defaults to session cwd, HELMD_CASES_DIR, or process cwd.' },\n      force: { type: 'boolean', description: 'Force open a new case even if an uncompleted open case exists on disk.' },\n    },\n    output: { schema: { type: 'string' }, render: (_a: unknown, v: string) => [{ type: 'text', text: v }] },\n    async execute(args: { goal: string; samples?: string[]; root?: string; force?: boolean }, exec?: ExecLike) {\n      const effectiveRoot = resolveWorkspaceRoot(args.root, exec)\n      const existing = getCase(exec?.agent?.id)\n      if (existing) {\n        return `A case is already active for this session: ${existing.name}\\nClose it with end_case() before opening another.`\n      }\n      if (!args.force) {\n        const openCase = await findOpenCaseOnDisk(effectiveRoot)\n        if (openCase) {\n          return [\n            `Notice: an unclosed case is already open on disk: ${openCase.name}`,\n            `Goal: ${openCase.goal}`,\n            '',\n            `Options:`,\n            `1. Resume it: call case_status(name: \"${openCase.name}\")`,\n            `2. Close it first: call end_case(summary: \"...\")`,\n            `3. Force new case: call begin_case(goal: \"...\", force: true)`,\n          ].join('\\n')\n        }\n      }\n      const mode = getLevel(exec?.agent?.id)\n      const info = await createCaseDir({\n        goal: args.goal ?? 'unspecified',\n        samples: args.samples ?? [],\n        mode,\n        route: 'pending (route_task)',\n        root: effectiveRoot,\n      })\n      bindCase(exec?.agent?.id, info)\n      // Optional team hook: settings.team.autoTicket opens a ticket per case so\n      // the model can dispatch immediately. Best-effort — a team failure must\n      // never block opening the case.\n      let teamNote = ''\n      if (loadSettings().team.autoTicket) {\n        try {\n          const ticket = createTicket({ goal: args.goal ?? info.goal, caseDir: info.dir })\n          teamNote = `team ticket: ${ticket.id} (${ticket.roles.map((r) => r.role).join(', ')}) — dispatch with team_dispatch`\n        } catch (error) {\n          teamNote = `team ticket: skipped (${error instanceof Error ? error.message : String(error)})`\n        }\n      }\n      return [\n        `case opened: ${info.dir}`,\n        `mode: ${mode}`,\n        ...(teamNote !== '' ? [teamNote] : []),\n        '',\n        RULES,\n      ].join('\\n')\n    },\n  }))\n\n  ctx.tools.register(defineTool({\n    name: 'case_status',\n    description:\n      'Re-read the active case state from disk (CASE.md header, samples, recent timeline). ' +\n      'Call this FIRST when resuming a task after context compaction — disk state survives what the conversation loses. ' +\n      'Can also resume an existing case by name or inspect cases on disk.',\n    parameters: {\n      name: { type: 'string', description: 'Optional case folder name to resume (or \"open\"/\"latest\" to rebind the most recent open case).' },\n      root: { type: 'string', description: 'Optional workspace root directory.' },\n    },\n    output: { schema: { type: 'string' }, render: (_a: unknown, v: string) => [{ type: 'text', text: v }] },\n    async execute(args: { name?: string; root?: string }, exec?: ExecLike) {\n      const effectiveRoot = resolveWorkspaceRoot(args.root, exec)\n      let active = getCase(exec?.agent?.id)\n\n      if (args.name) {\n        if (args.name === 'open' || args.name === 'latest') {\n          const found = await findOpenCaseOnDisk(effectiveRoot)\n          if (found) {\n            bindCase(exec?.agent?.id, found)\n            active = found\n          } else {\n            return `No unclosed open case found on disk under ${casesRoot(effectiveRoot)}.`\n          }\n        } else {\n          const fromDisk = await loadCaseInfoFromDisk(args.name, effectiveRoot)\n          if (fromDisk) {\n            bindCase(exec?.agent?.id, fromDisk)\n            active = fromDisk\n          } else {\n            return `Case '${args.name}' not found under ${casesRoot(effectiveRoot)}.`\n          }\n        }\n      }\n\n      if (!active) {\n        const base = casesRoot(effectiveRoot)\n        const audit = await auditCasesRoot(effectiveRoot)\n        const parts: string[] = [\n          `No case bound to this session. Recent case dirs (if any) live under ${base} — inspect and re-run begin_case if resuming.`,\n        ]\n        if (audit.cases.length > 0) {\n          parts.push('\\nCases on disk:')\n          for (const c of audit.cases.slice(0, 5)) {\n            parts.push(`  - ${c.name} [${c.status}] (${c.evidenceCount} evidence): ${c.goal.slice(0, 60)}`)\n          }\n        }\n        if (audit.strays.length > 0) {\n          parts.push(`\\n[Notice] Non-case items found under helmd-cases: ${audit.strays.join(', ')}`)\n        }\n        const openCase = audit.cases.find((c) => c.status === 'open')\n        if (openCase) {\n          parts.push(`\\nActive unclosed case: ${openCase.name}. To resume: case_status(name: \"${openCase.name}\")`)\n        }\n        return parts.join('\\n')\n      }\n\n      const md = await loadCaseMd(active.dir)\n      const lines = md.split('\\n')\n      const head = lines.slice(0, lines.indexOf('## timeline') >= 0 ? lines.indexOf('## timeline') : 12).join('\\n')\n      const timeline = lines.filter((l) => l.startsWith('- [')).slice(-5).join('\\n')\n      // The resume block is the handoff contract: it must survive a truncated window.\n      const resumeAt = lines.findIndex((l) => l.startsWith('## resume'))\n      const resume = resumeAt >= 0 ? lines.slice(resumeAt).join('\\n').trim() : ''\n\n      const loose = await listLooseFilesInCase(active.dir)\n      const looseNotice = loose.length > 0\n        ? `\\n\\n[Warning] ${loose.length} loose unorganized file(s) in case root (will auto-archive to evidence/ on end_case): ${loose.join(', ')}`\n        : ''\n      const hypotheses = await loadHypotheses(active.dir)\n      const findings = await loadFindings(active.dir)\n      const evidence = await listEvidence(active.dir)\n      const bySeverity = severityCounts(findings)\n      const byStatus = findingStatusCounts(findings)\n      const findingStats = findings.length === 0\n        ? 'findings: none'\n        : `findings: ${findings.length} — critical ${bySeverity.critical} · high ${bySeverity.high} · medium ${bySeverity.medium} · low ${bySeverity.low} · info ${bySeverity.info} | verified ${byStatus.verified} · candidate ${byStatus.candidate} · rejected ${byStatus.rejected} · duplicate ${byStatus.duplicate} · wontfix ${byStatus.wontfix}`\n      const packet = loadSettings().advisory.autonomyPacket\n        ? renderAutonomyPacket({\n          mode: getLevel(exec?.agent?.id),\n          goal: active.goal,\n          hypotheses,\n          findings,\n          evidence,\n        })\n        : ''\n\n      return [\n        `case: ${active.name}`,\n        `dir: ${active.dir}`,\n        '',\n        head,\n        '',\n        'recent timeline:',\n        timeline || '  (empty)',\n        looseNotice,\n        ...(resume ? ['', resume] : []),\n        ...(packet !== '' ? ['', packet] : []),\n        '',\n        findingStats,\n        '',\n        RULES,\n        ...(renderAdvisoryStats() ? ['', renderAdvisoryStats()] : []),\n        ...(getStreamInterceptionStats().count > 0\n          ? ['', `[流式拒答拦截监控]\\n已拦截拒答: ${getStreamInterceptionStats().count} 次 | 最近拦截: ${getStreamInterceptionStats().lastTime || '无'}\\n审计日志文件: ${getStreamInterceptionStats().logFile}`]\n          : ['', `[流式拒答拦截监控]\\n状态: 监控中 (当前会话拦截 0 次) | 审计日志文件: ${getStreamInterceptionStats().logFile}`]),\n      ].join('\\n')\n    },\n  }))\n\n  ctx.tools.register(defineTool({\n    name: 'record_finding',\n    description:\n      'Register a finding in the case register (findings.json + findings.md). severity is required; CVSS (when given) is ' +\n      'authoritative and the asserted value is kept for audit. critical/high need >= 2 evidence ids and non-unverified ' +\n      'confidence, otherwise the severity is downgraded. Identical vuln_class+target+title merges into the existing finding. ' +\n      'Every evidence id is validated; citing unknown ids or self-authored evidence is rejected.',\n    parameters: {\n      title: { type: 'string', required: true, description: 'Finding title, e.g. \"License check is a plaintext base64 compare\".' },\n      detail: { type: 'string', required: true, description: 'What was found, how it was observed, and the impact.' },\n      evidence_ids: { type: 'array', items: { type: 'string' }, required: true, description: 'e.g. [\"E-002\",\"E-005\"].' },\n      repro_cmd: { type: 'string', required: true, description: 'Reusable command/tool call that reproduces the conclusion.' },\n      severity: {\n        type: 'string',\n        required: true,\n        description: `One of: ${FINDING_SEVERITIES.join(' | ')}. critical/high require >= 2 evidence ids.`,\n      },\n      vuln_class: { type: 'string', description: 'Vulnerability class, e.g. auth-bypass / xss / license-bypass; used for dedup.' },\n      target: { type: 'string', description: 'Affected target/endpoint/file; used for dedup.' },\n      confidence: { type: 'string', description: `One of: ${FINDING_CONFIDENCES.join(' | ')} (default probable). unverified caps severity at medium.` },\n      cvss: { type: 'number', description: 'CVSS v3 score 0-10; when supplied it overrides severity by the standard bands.' },\n      status: { type: 'string', description: `Initial triage state: ${FINDING_STATUSES.join(' | ')} (default verified after the gates).` },\n    },\n    output: { schema: { type: 'string' }, render: (_a: unknown, v: string) => [{ type: 'text', text: v }] },\n    async execute(\n      args: {\n        title: string\n        detail: string\n        evidence_ids: string[]\n        repro_cmd: string\n        severity: string\n        vuln_class?: string\n        target?: string\n        confidence?: string\n        cvss?: number\n        status?: string\n      },\n      exec?: ExecLike,\n    ) {\n      const active = getCase(exec?.agent?.id)\n      if (!active) return 'No active case. begin_case() first — findings need an evidence chain.'\n      const check = await validateEvidenceIds(active.dir, args.evidence_ids ?? [])\n      if (!check.ok) {\n        return [\n          `REJECTED — unknown evidence ids: ${check.missing.join(', ')}`,\n          `known ids: ${check.known.join(', ') || '(none)'}`,\n          'Cite only ids that exist in evidence/. Run the tool that produces the proof first.',\n        ].join('\\n')\n      }\n      if ((args.repro_cmd ?? '').trim() === '') {\n        return 'REJECTED — repro_cmd is required: a finding without a reproducible command is not a conclusion.'\n      }\n      // Anti-pretence gates. The model can CLAIM it read references or ran a\n      // tool; these checks read the actual evidence filenames (produced by the\n      // persisting wrapper) and the session's real tool/call trace instead.\n      const discipline = loadSettings().advisory\n      if (discipline.requireToolEvidence) {\n        const onDisk = await listEvidence(active.dir)\n        const byId = new Map(onDisk.map((entry) => [entry.id, entry.file]))\n        const citedFiles = (args.evidence_ids ?? []).map((id) => byId.get(id)).filter((file): file is string => file !== undefined)\n        // `manual_` is the reserved prefix save_evidence stamps on every\n        // model-authored capture, so a spoofed label can never pass as tool output.\n        const selfAuthored = /^E-\\d+-(manual_|save_evidence|team_report)/\n        if (!citedFiles.some((file) => !selfAuthored.test(file))) {\n          return [\n            'REJECTED — every cited evidence id is self-authored (save_evidence/team_report).',\n            `cited: ${citedFiles.join(', ') || '(none)'}`,\n            'Run a real analysis tool first; its output is auto-captured as evidence with the tool name in the filename.',\n          ].join('\\n')\n        }\n      }\n      if (discipline.requireDocRead) {\n        const calls = toolCalls(sessionEvents(exec?.agent as unknown as Parameters<typeof sessionEvents>[0], 'caseflow'))\n        if (!calls.some((call) => call.name === 'read_reference')) {\n          return [\n            'REJECTED — no read_reference call found in this session\\'s real tool trace.',\n            'Call route_task(goal) and then read_reference(<matched refs>) before recording a conclusion;',\n            'the claim \"I read the docs\" is not evidence.',\n          ].join('\\n')\n        }\n      }\n      try {\n        const recorded = await recordFinding(active.dir, {\n          title: args.title,\n          detail: args.detail,\n          evidenceIds: args.evidence_ids ?? [],\n          severity: args.severity as FindingSeverity,\n          vulnClass: args.vuln_class,\n          target: args.target,\n          confidence: args.confidence as FindingConfidence | undefined,\n          cvss: typeof args.cvss === 'number' ? args.cvss : undefined,\n          status: args.status as FindingStatus | undefined,\n          repro: args.repro_cmd,\n        })\n        const f = recorded.finding\n        return [\n          `${recorded.merged ? 'finding merged' : 'finding recorded'}: ${f.id} [${f.severity}/${f.status}] ${f.title}`,\n          `evidence: ${f.evidenceIds.join(', ')} | vuln_class: ${f.vulnClass}${f.cvss !== undefined ? ` | cvss: ${f.cvss}` : ''}${f.assertedSeverity ? ` | asserted: ${f.assertedSeverity}` : ''}`,\n          ...(recorded.notes.length > 0 ? [`rules: ${recorded.notes.join('; ')}`] : []),\n          `repro: ${args.repro_cmd.trim()}`,\n        ].join('\\n')\n      } catch (error) {\n        return `REJECTED — ${error instanceof Error ? error.message : String(error)}`\n      }\n    },\n  }))\n\n  ctx.tools.register(defineTool({\n    name: 'update_finding',\n    description:\n      'Move one finding through its triage lifecycle (candidate → verified → rejected/duplicate/wontfix) or correct its ' +\n      'severity with an audit note. Evidence and repro are immutable; use a new record_finding for new evidence.',\n    parameters: {\n      finding_id: { type: 'string', required: true, description: 'F-xxx id from the finding register.' },\n      status: { type: 'string', description: `New status: ${FINDING_STATUSES.join(' | ')}.` },\n      severity: { type: 'string', description: `Corrected severity: ${FINDING_SEVERITIES.join(' | ')}.` },\n      note: { type: 'string', description: 'Why the triage changed (written to the case timeline).' },\n    },\n    output: { schema: { type: 'string' }, render: (_a: unknown, v: string) => [{ type: 'text', text: v }] },\n    async execute(args: { finding_id: string; status?: string; severity?: string; note?: string }, exec?: ExecLike) {\n      const active = getCase(exec?.agent?.id)\n      if (!active) return 'No active case. begin_case() first.'\n      try {\n        const updated = await updateFinding(active.dir, args.finding_id, {\n          status: args.status as FindingStatus | undefined,\n          severity: args.severity as FindingSeverity | undefined,\n          note: args.note,\n        })\n        if (updated === undefined) return `REJECTED — unknown finding id: ${args.finding_id}`\n        return `finding updated: ${updated.id} [${updated.severity}/${updated.status}] ${updated.title}`\n      } catch (error) {\n        return `REJECTED — ${error instanceof Error ? error.message : String(error)}`\n      }\n    },\n  }))\n\n  ctx.tools.register(defineTool({\n    name: 'record_hypothesis',\n    description:\n      'State a testable hypothesis before running tools. Forces you to think: what do you expect to find, ' +\n      'and how will you verify it? Returns H-xxx. Use update_hypothesis after testing.',\n    parameters: {\n      statement: { type: 'string', required: true, description: 'What you think is true.' },\n      expected: { type: 'string', required: true, description: 'What you expect to observe if true.' },\n      test_cmd: { type: 'string', required: true, description: 'Shell command or tool call to verify.' },\n      evidence_ids: { type: 'array', items: { type: 'string' }, description: 'Supporting evidence already collected.' },\n    },\n    output: { schema: { type: 'string' }, render: (_a: unknown, v: string) => [{ type: 'text', text: v }] },\n    async execute(args: { statement: string; expected: string; test_cmd: string; evidence_ids?: string[] }, exec?: ExecLike) {\n      const active = getCase(exec?.agent?.id)\n      if (!active) return 'No active case. begin_case() first — hypotheses need a case.'\n      const all = await loadHypotheses(active.dir)\n      const open = all.filter((h) => h.status === 'open')\n      if (open.length >= 1) {\n        return [\n          `REJECTED — ${open.length} open hypothesis already exists: ${open.map((h) => h.id).join(', ')}.`,\n          'Resolve it first with update_hypothesis before creating a new one.',\n        ].join('\\n')\n      }\n      const h = await recordHypothesis(active.dir, args.statement, args.expected, args.test_cmd, args.evidence_ids ?? [])\n      return [\n        `hypothesis ${h.id} recorded (open):`,\n        `  statement: ${h.statement}`,\n        `  expected:  ${h.expected}`,\n        `  test_cmd:  ${h.testCmd}`,\n        `Run the test, then update_hypothesis(id=\"${h.id}\", status=..., observation=..., evidence_ids=[...])`,\n      ].join('\\n')\n    },\n  }))\n\n  ctx.tools.register(defineTool({\n    name: 'update_hypothesis',\n    description:\n      'Resolve a hypothesis after testing. Status must be confirmed / refuted / blocked. ' +\n      'confirmed and refuted require an observation and at least one evidence id.',\n    parameters: {\n      id: { type: 'string', required: true, description: 'Hypothesis id, e.g. \"H-001\".' },\n      status: { type: 'string', required: true, description: 'confirmed | refuted | blocked.' },\n      observation: { type: 'string', required: true, description: 'What you actually observed.' },\n      evidence_ids: { type: 'array', items: { type: 'string' }, description: 'Evidence supporting the verdict.' },\n    },\n    output: { schema: { type: 'string' }, render: (_a: unknown, v: string) => [{ type: 'text', text: v }] },\n    async execute(args: { id: string; status: string; observation: string; evidence_ids?: string[] }, exec?: ExecLike) {\n      const active = getCase(exec?.agent?.id)\n      if (!active) return 'No active case.'\n      if (!['confirmed', 'refuted', 'blocked'].includes(args.status)) {\n        return `REJECTED — status must be confirmed | refuted | blocked, got \"${args.status}\".`\n      }\n      if (args.status !== 'blocked' && (args.evidence_ids ?? []).length === 0) {\n        return `REJECTED — ${args.status} requires at least one evidence id. Run the test first.`\n      }\n      if (args.evidence_ids && args.evidence_ids.length > 0) {\n        const check = await validateEvidenceIds(active.dir, args.evidence_ids)\n        if (!check.ok) {\n          return `REJECTED — unknown evidence ids: ${check.missing.join(', ')}. Known: ${check.known.join(', ') || '(none)'}.`\n        }\n      }\n      const h = await updateHypothesis(active.dir, args.id, args.status as any, args.observation, args.evidence_ids ?? [])\n      if (!h) return `REJECTED — hypothesis ${args.id} not found.`\n      return `hypothesis ${h.id} → ${h.status}. ${h.observation?.slice(0, 120) ?? ''}`\n    },\n  }))\n\n  ctx.tools.register(defineTool({\n    name: 'end_case',\n    description:\n      'Close the active case: stamps CASE.md completed and unbinds the session. ' +\n      'In deep mode at least one recorded finding is required, and every finding must carry repro_cmd. ' +\n      'Closing also requires at least one evidence entry on disk, unless the summary states why there is none ' +\n      'with \"(no-evidence: …)\".',\n    parameters: { summary: { type: 'string', description: 'One-line closing summary.' } },\n    output: { schema: { type: 'string' }, render: (_a: unknown, v: string) => [{ type: 'text', text: v }] },\n    async execute(args: { summary?: string }, exec?: ExecLike) {\n      const active = getCase(exec?.agent?.id)\n      if (!active) return 'No active case bound to this session.'\n      const mode = getLevel(exec?.agent?.id)\n      if (mode === 'deep') {\n        const findings = await loadFindings(active.dir)\n        if (findings.length === 0) {\n          return 'DEEP mode requires at least one record_finding before end_case. Evidence chain incomplete.'\n        }\n        const missingRepro = findings.filter((finding) => (finding.repro ?? '').trim() === '')\n        if (missingRepro.length > 0) {\n          return [\n            `REJECTED — DEEP mode requires repro_cmd on every finding: ${missingRepro.map((f) => f.title).join(', ')}.`,\n            'Re-record the finding with repro_cmd (a command that reproduces it) before closing.',\n          ].join('\\n')\n        }\n      }\n      // Hypothesis gate: all hypotheses must be resolved before closing.\n      const openCount = await getOpenHypothesisCount(active.dir)\n      if (openCount > 0) {\n        const all = await loadHypotheses(active.dir)\n        const open = all.filter((h) => h.status === 'open')\n        return [\n          `REJECTED — ${openCount} open hypothesis(es) must be resolved before closing:`,\n          ...open.map((h) => `  ${h.id}: ${h.statement} (test: ${h.testCmd})`),\n          'Use update_hypothesis(id, status, observation, evidence_ids) to resolve each one.',\n        ].join('\\n')\n      }\n      // Completion is an external fact, not a self-report: a closed case must point at\n      // evidence on disk, or say in words why it has none.\n      const evidence = await countEvidence(active.dir)\n      if (evidence === 0 && !/\\(no-evidence:\\s*\\S/i.test(args.summary ?? '')) {\n        return [\n          'REJECTED — 关闭前必须交代证据：evidence/ 里一条 E-xxx 都没有。',\n          '两条路径：① 先落地证据（跑工具，或 save_evidence(label, ...)）再关闭；',\n          '② 本次确实无证据（纯咨询 / 被阻塞）就在 summary 里写明：',\n          '   summary: \"… (no-evidence: 用户仅咨询，未接触样本)\"。',\n        ].join('\\n')\n      }\n      await closeCase(active.dir, args.summary)\n      unbindCase(exec?.agent?.id)\n      const stats = renderAdvisoryStats()\n      return [`case closed: ${active.name}${args.summary ? ` — ${args.summary}` : ''}`, ...(stats ? ['', stats] : [])].join('\\n')\n    },\n  }))\n\n  ctx.tools.register(defineTool({\n    name: 'save_evidence',\n    description:\n      'Persist arbitrary output into the active case evidence chain with an E-number. ' +\n      'Use for external CLI tools run via shell whose output would otherwise leave no trace. ' +\n      'Findings may cite these ids exactly like tool-generated ones.',\n    parameters: {\n      label: { type: 'string', required: true, description: 'Short source label, e.g. \"themida-dump\".' },\n      content: { type: 'string', description: 'Text to store.' },\n      file: { type: 'string', description: 'Path of a file to store instead of inline content.' },\n    },\n    output: { schema: { type: 'string' }, render: (_a: unknown, v: string) => [{ type: 'text', text: v }] },\n    async execute(args: { label: string; content?: string; file?: string }, exec?: ExecLike) {\n      const active = getCase(exec?.agent?.id)\n      if (!active) return 'No active case. begin_case() first — evidence needs a home.'\n      let content = args.content ?? ''\n      if (!content && args.file) {\n        if (!existsSync(resolve(args.file))) return `file not found: ${args.file}`\n        content = `<copied from file: ${resolve(args.file)}>\\n` +\n          await import('node:fs/promises').then((m) => m.readFile(resolve(args.file!), 'utf8'))\n      }\n      if (!content.trim()) return 'nothing to save (empty content)'\n      // Reserved provenance prefix: the anti-pretence gate keys off the filename,\n      // so a model-controlled label must never look like a tool name.\n      const { id } = await saveEvidence(active.dir, `manual_${args.label}`, content, args.label)\n      return `[evidence: ${id} saved to ${active.name}]`\n    },\n  }))\n}\n"
    },
    {
      "path": "packages/helmd/src/health.ts",
      "content": "/**\n * Host-plane health surface for the helmd package.\n *\n * Evaluates the package-internal preset patch (`preset.generated.patch.yml`,\n * written by gen-preset.mjs and loaded through `dsh.bundle.patch`) against the\n * hash of the INSTALLED host's own `standard` preset patch, and serves the\n * verdict at `GET /api/helmd/health`.\n *\n * 0.1.7 moved presets from a deployed `.agent-presets/<name>/agent.cordis.yml`\n * to a composition row, so this package now carries its own preset artifact and\n * there is no deployment step to drift: drift here means the shipped artifact\n * was generated against a different host standard (HOST_UPGRADED) or no longer\n * satisfies the structural assertion (STALE).\n *\n * Evaluation runs once per process start — deliberately. The standing-mount\n * semantics mean a preset change is only safe after a harness restart\n * (incident 2026-08-26: generation replacement collides in the same preset\n * scope), so boot time is exactly the moment this verdict is true.\n *\n * The verdict is derived state, not configuration: 0.1.7's settings document\n * only carries Config schemas of profile entries, so the card reads the HTTP\n * route instead of a settings namespace. Agent tools are mounted by the preset\n * row; keeping this row on the host plane makes the health card available\n * without exposing helmd tools to other agents.\n */\nimport { createHash } from 'node:crypto'\nimport { spawnSync } from 'node:child_process'\nimport { copyFileSync, existsSync, readFileSync } from 'node:fs'\nimport { join, resolve } from 'node:path'\nimport { fileURLToPath } from 'node:url'\nimport type { Context } from '@deepseek-ai/cordis'\nimport z from '@deepseek-ai/schemastery'\nimport { registerHelmdApi } from './api-routes.js'\nimport { saveSettings } from './settings.js'\n\n/**\n * Composition-row Config. Exposing this schema is what puts helm-d into the\n * DSH settings page (SettingsForms renders Config schemas of active rows).\n * Values edited there live in the profile patch and are merged over\n * storages/helmd/settings.json at boot — the workbench 设置 tab edits the same\n * store for the running process.\n */\nexport const Config = z.object({\n  team: z.object({\n    autoTicket: z.boolean().default(false).description('begin_case 时自动创建 team ticket'),\n    defaultRoles: z.array(z.string()).default(['triage', 'static', 'critic', 'reporter'])\n      .description('新 ticket 的默认角色集'),\n    maxParallelWorkers: z.number().min(1).max(8).default(4).description('每 ticket 同时运行的 worker 上限'),\n    defaultWallTimeMin: z.number().min(1).max(60).default(15).description('worker 默认超时（分钟）'),\n  }),\n  intercept: z.object({\n    enabled: z.boolean().default(true).description('流式拒绝拦截总开关'),\n  }),\n  advisory: z.object({\n    autonomyPacket: z.boolean().default(true).description('case_status 附 [autonomy] 状态包'),\n    nextActionNudge: z.boolean().default(true).description('工具结果后的下一步建议'),\n    requireDocRead: z.boolean().default(true).description('record_finding 前必须真实调用过 read_reference'),\n    requireToolEvidence: z.boolean().default(true).description('引用证据至少一条来自真实工具捕获（非 save_evidence 自编）'),\n  }),\n  star: z.object({\n    popupDelaySec: z.number().min(0).max(60).default(2).description('Star 弹窗延迟秒数'),\n  }),\n  toolbox: z.object({\n    modelInstall: z.boolean().default(false).description('允许模型安装 catalog 内的外部工具（默认关闭）'),\n  }),\n})\n\n/** Legacy settings namespace; now only the client health-card key. */\nexport const HELMD_HEALTH_NS = 'helmd'\n\nconst FINGERPRINT_RE = /^# gen-preset: host=([0-9a-f]{64})/m\n\n/** Health verdict served to the settings card. All fields are plain strings. */\nexport interface HelmdHealth {\n  /** OK | HOST_UPGRADED | STALE | LEGACY_PRESET | NOT_GENERATED | UNKNOWN */\n  status: string\n  /** Human-readable one-liner supporting the status. */\n  detail: string\n  /** sha256 of the installed host standard, first 12 hex chars ('' if unreadable). */\n  hostFingerprint: string\n  /** Fingerprint recorded inside the generated preset patch ('' if absent). */\n  presetFingerprint: string\n  /** Absolute path of this package's generated preset patch ('' if not found). */\n  presetPath: string\n  /** Absolute path of the host standard used ('' if not found). */\n  hostPath: string\n  /** ISO timestamp of this evaluation (host boot). */\n  checkedAt: string\n  /** Installed helmd package version. */\n  version: string\n  /**\n   * Drift-repair verdict: `healed (<from> → <to>) — …` when the preset was rewritten;\n   * `<status> not repaired — …` or `off (HELMD_AUTO_HEAL=0)` when it was left alone;\n   * `unavailable (…)` / `failed (…)` otherwise.\n   */\n  autoHeal: string\n}\n\n/** Preset-patch tails per host generation, newest first (mirrors gen-preset.mjs). */\nconst HOST_STANDARD_TAILS: string[][] = [\n  ['@deepseek-ai', 'dsh', 'node_modules', '@deepseek-ai', 'dsh-web-app', 'presets', 'standard.patch.yml'],\n  ['@deepseek-ai', 'dsh', 'node_modules', '@deepseek-ai', 'dsh-agent-presets', 'presets', 'standard', 'agent.cordis.yml'],\n  ['@deepseek-ai', 'dsh', 'config', 'agent-presets', 'standard', 'agent.cordis.yml'],\n]\n\n/**\n * Locate the installed dsh's shipped standard preset without spawning npm\n * (this runs on the session server). Same probe order as scripts/gen-preset.mjs.\n */\nfunction locateHostStandard(): string | null {\n  const env = process.env.DSH_HOST_STANDARD_YML\n  if (env && existsSync(env)) return env\n  const bases = [\n    process.env.APPDATA ? join(process.env.APPDATA, 'npm', 'node_modules') : '',\n    '/usr/local/lib/node_modules',\n    '/usr/lib/node_modules',\n  ]\n  // The official installer puts dsh beside its own binary, so a PATH entry is a\n  // candidate install prefix as well.\n  const sep = process.platform === 'win32' ? ';' : ':'\n  for (const raw of (process.env.PATH ?? '').split(sep)) {\n    const dir = raw.replace(/[\\\\/]+$/, '')\n    if (dir !== '') bases.push(join(dir, 'node_modules'), join(dir, 'lib', 'node_modules'))\n  }\n  for (const b of bases) {\n    if (b === '') continue\n    for (const tail of HOST_STANDARD_TAILS) {\n      const c = join(b, ...tail)\n      if (existsSync(c)) return c\n    }\n  }\n  return null\n}\n\n/**\n * This package's generated preset patch — the artifact the host actually loads\n * through `dsh.bundle.patch`. `HELMD_PRESET_PATCH` redirects it for tests.\n */\nfunction presetPatchPath(): string {\n  const env = process.env.HELMD_PRESET_PATCH?.trim()\n  if (env) return resolve(env)\n  try {\n    return fileURLToPath(new URL('../preset.generated.patch.yml', import.meta.url))\n  } catch {\n    return ''\n  }\n}\n\nconst HEALABLE = new Set(['HOST_UPGRADED', 'STALE', 'LEGACY_PRESET'])\n\n/**\n * Drift-repair policy:\n *   unset → repair a deployed preset that carries our fingerprint header (provenance is\n *           provable: it is an artifact we generated), and only report one without a\n *           header (it may be hand-written, so overwriting it is the user's call);\n *   `0`   → never write — escape hatch for a locked-down or hand-managed deployment;\n *   `1`   → repair every healable status, header or not.\n * A repair keeps the previous file as `.bak` first. Restarting dsh and asserting the\n * catalog (MAINTENANCE §8) stays the user's step: this only re-syncs the file.\n */\nfunction healPolicy(): 'auto' | 'off' | 'force' {\n  const flag = process.env.HELMD_AUTO_HEAL?.trim().toLowerCase()\n  if (flag === '0' || flag === 'false' || flag === 'no') return 'off'\n  if (flag === '1' || flag === 'true' || flag === 'yes') return 'force'\n  return 'auto'\n}\n\n/** Statuses whose deployed file carries the gen-preset header, i.e. provably our artifact. */\nconst DERIVED_STATUSES = new Set(['STALE', 'HOST_UPGRADED'])\n\nfunction shouldRepair(status: string, policy: 'auto' | 'off' | 'force'): boolean {\n  if (policy === 'off') return false\n  if (policy === 'force') return true\n  return DERIVED_STATUSES.has(status)\n}\n\n/** Why a healable status was left alone. */\nfunction reportOnlyVerdict(status: string, policy: 'auto' | 'off' | 'force'): string {\n  if (policy === 'off') return 'off (HELMD_AUTO_HEAL=0)'\n  return `${status} not repaired — no gen-preset fingerprint header, so the file is not provably ours; `\n    + 'regenerate with install / setup-preset, or set HELMD_AUTO_HEAL=1 to overwrite it (a .bak is kept)'\n}\n\n/** Locate the bundled generator that rewrites the deployed preset from the host standard. */\nfunction resolveGenerator(): string | null {\n  try {\n    const p = resolve(fileURLToPath(new URL('.', import.meta.url)), '..', 'scripts', 'gen-preset.mjs')\n    return existsSync(p) ? p : null\n  } catch {\n    return null\n  }\n}\n\n/**\n * Top-level plugin-row ids of either preset shape (mirrors gen-preset.mjs):\n * ids directly under a `plugins:` list (0.1.7 — group children sit deeper and\n * are skipped), or column-0 `- id:` rows of a legacy agent.cordis.yml.\n */\nfunction rowIds(text: string): string[] {\n  const lines = text.replace(/\\r\\n/g, '\\n').split('\\n')\n  const pi = lines.findIndex((l) => /^\\s*plugins:\\s*$/.test(l))\n  if (pi < 0) return [...text.matchAll(/^- id: (.+)$/gm)].map((m) => m[1].trim())\n  const pIndent = lines[pi].length - lines[pi].trimStart().length\n  const base = pIndent + 2\n  const out: string[] = []\n  for (let i = pi + 1; i < lines.length; i++) {\n    const line = lines[i]\n    if (!line.trim()) continue\n    const ind = line.length - line.trimStart().length\n    if (ind <= pIndent) break\n    if (ind !== base) continue\n    const m = line.trimStart().match(/^-\\s+id:\\s*(.+)$/)\n    if (m) out.push(m[1].trim())\n  }\n  return out\n}\n\n/**\n * Structural half of the MAINTENANCE §8 guardrail: everything assertable about the artifact\n * itself, with no session involved. The live half (a restarted host answers the first\n * request with exactly [pwsh, read] on Windows / [bash, read] elsewhere) stays with the\n * operator — it cannot be produced from inside the process that is being asserted.\n */\nexport function assertPresetArtifact(deployed: string, hostStandardText: string): { ok: boolean; detail: string } {\n  const hostIds = rowIds(hostStandardText)\n  const deployedIds = rowIds(deployed)\n  // tool-agent-team rides INSIDE the helmd preset's plugins list (host-native\n  // experimental team tools, helmd-scoped); the agent-team service row sits at\n  // the composition top level, outside any plugins block, so rowIds never sees it.\n  const expected = [...hostIds, 'helmd', 'tool-agent-team'].sort()\n  if (JSON.stringify([...deployedIds].sort()) !== JSON.stringify(expected)) {\n    return {\n      ok: false,\n      detail: `row ids differ from this host's standard (expected ${expected.length}: host rows + helmd, got ${deployedIds.length})`,\n    }\n  }\n  const duplicated = [...new Set(deployedIds.filter((id, i) => deployedIds.indexOf(id) !== i))]\n  if (duplicated.length > 0) return { ok: false, detail: `duplicated row ids: ${duplicated.join(', ')}` }\n  if (!deployed.includes('- id: preset-helmd') || !deployed.includes('id: helmd')) {\n    return { ok: false, detail: 'the preset entry is not retargeted at helmd (`- id: preset-helmd` / `id: helmd`)' }\n  }\n  if (!deployed.includes(\"'@deepseek-ai/dsh-agent-preset'\")) {\n    return { ok: false, detail: 'the entry does not declare @deepseek-ai/dsh-agent-preset' }\n  }\n  if ((deployed.match(/@adwmc\\/helm-d/g) ?? []).length !== 1) {\n    return { ok: false, detail: 'the helmd row is not declared exactly once' }\n  }\n  // v2: the persona ships sealed in profiles.dat — the patch carries an EMPTY\n  // persona prefix. The activation line lives in presets/profiles/ds4.1f.md\n  // (sealed at build), so the patch-level check below is retired.\n  return { ok: true, detail: `${deployedIds.length} rows (host standard + helmd; persona via sealed profiles)` }\n}\n\n/** Run the artifact assertion against the evaluated paths; unreadable inputs report no verdict. */\nfunction artifactVerdict(health: HelmdHealth): string {\n  try {\n    const deployed = readFileSync(health.presetPath, 'utf8')\n    const host = readFileSync(health.hostPath, 'utf8')\n    const result = assertPresetArtifact(deployed, host)\n    return result.ok ? `artifact check OK (${result.detail})` : `ARTIFACT CHECK FAILED: ${result.detail}`\n  } catch {\n    return 'artifact check skipped (files unreadable)'\n  }\n}\n\n/**\n * Regenerate this package's preset patch from the installed host standard. The caller has\n * already decided (via {@link shouldRepair}) that writing is allowed; this only performs it\n * and keeps the previous file as `.bak` first.\n */\nfunction autoHealPreset(): { healed: boolean; verdict: string } {\n  const gen = resolveGenerator()\n  if (gen === null) return { healed: false, verdict: 'unavailable (no generator)' }\n  const target = presetPatchPath()\n  if (target === '') return { healed: false, verdict: 'failed (preset patch path is unresolved)' }\n  try {\n    if (existsSync(target)) {\n      try {\n        copyFileSync(target, `${target}.bak`)\n      } catch {\n        // A failed backup must not block the repair; the exit status below still reports it.\n      }\n    }\n    const res = spawnSync(process.execPath, [gen, '--out', target], {\n      encoding: 'utf8',\n      timeout: 60_000,\n    })\n    if (res.status !== 0) {\n      const why = String(res.stderr || res.error?.message || '').trim().split('\\n').slice(-1)[0] ?? ''\n      return { healed: false, verdict: `failed (exit ${String(res.status)}${why ? `: ${why}` : ''})` }\n    }\n    const anchor = process.platform === 'win32' ? '[pwsh, read]' : '[bash, read]'\n    return { healed: true, verdict: `restart dsh and assert the first request is ${anchor} (MAINTENANCE §8)` }\n  } catch (e) {\n    return { healed: false, verdict: `failed (${(e as Error).message})` }\n  }\n}\n\nfunction evaluateHealthCore(): HelmdHealth {\n  let version = ''\n  try {\n    const pkgUrl = new URL('../package.json', import.meta.url)\n    version = JSON.parse(readFileSync(pkgUrl, 'utf8')).version ?? ''\n  } catch { /* keep '' */ }\n\n  const base: HelmdHealth = {\n    status: 'UNKNOWN',\n    detail: '',\n    hostFingerprint: '',\n    presetFingerprint: '',\n    presetPath: '',\n    hostPath: '',\n    checkedAt: new Date().toISOString(),\n    version,\n    autoHeal: 'off',\n  }\n\n  const hostPath = locateHostStandard()\n  base.hostPath = hostPath ?? ''\n  if (hostPath === null) {\n    base.status = 'UNKNOWN'\n    base.detail = 'cannot locate the installed dsh standard preset; set DSH_HOST_STANDARD_YML'\n    return base\n  }\n  let hostHash = ''\n  try {\n    hostHash = createHash('sha256').update(readFileSync(hostPath, 'utf8'), 'utf8').digest('hex')\n    base.hostFingerprint = hostHash.slice(0, 12)\n  } catch {\n    base.status = 'UNKNOWN'\n    base.detail = `host standard at ${hostPath} is unreadable`\n    return base\n  }\n\n  const presetPath = presetPatchPath()\n  base.presetPath = presetPath\n  if (presetPath === '' || !existsSync(presetPath)) {\n    base.status = 'NOT_GENERATED'\n    base.detail = `this package ships no generated preset patch (${presetPath || 'unresolved path'}); run node scripts/gen-preset.mjs or repack, then restart`\n    return base\n  }\n\n  let text = ''\n  try { text = readFileSync(presetPath, 'utf8') } catch {\n    base.status = 'UNKNOWN'\n    base.detail = `preset patch ${presetPath} is unreadable`\n    return base\n  }\n  const m = text.match(FINGERPRINT_RE)\n  if (!m) {\n    base.presetFingerprint = ''\n    base.status = 'LEGACY_PRESET'\n    base.detail = 'preset patch carries no gen-preset fingerprint header, so it is not this generator\\'s output; regenerate (repack / gen-preset), or set HELMD_AUTO_HEAL=1 to overwrite it (a .bak is kept)'\n    return base\n  }\n  base.presetFingerprint = m[1].slice(0, 12)\n  if (m[1] !== hostHash) {\n    base.status = 'HOST_UPGRADED'\n    base.detail = `preset patch targets dsh ${base.presetFingerprint} but the host now hashes ${base.hostFingerprint}; regenerate (repack / gen-preset), or HELMD_AUTO_HEAL=1 + restart`\n    return base\n  }\n  // Same host standard, so the header says nothing more: the remaining question is\n  // whether the artifact still satisfies the structural assertion. It can fail with\n  // the header unmoved — a hand-edit, or a persona change that was never re-synced —\n  // which is the drift the badge exists for.\n  const artifact = artifactVerdict(base)\n  if (!artifact.startsWith('artifact check OK')) {\n    base.status = 'STALE'\n    base.detail = `preset patch matches the host fingerprint ${base.hostFingerprint} but fails its structural assertion; ${artifact}; regenerate with repack / gen-preset, or HELMD_AUTO_HEAL=1 + restart`\n    return base\n  }\n  base.status = 'OK'\n  // The structural half of MAINTENANCE §8 is cheap and worth stating on every boot: it is\n  // the assertion that would have caught the 2026-08-26 crippled-catalog preset.\n  base.detail = `preset patch matches installed dsh standard (${base.hostFingerprint}); ${artifact}`\n  return base\n}\n\n/**\n * Evaluate the preset patch fingerprint and, when it drifted, optionally regenerate it\n * from the installed host standard (`HELMD_AUTO_HEAL=1` opts in; default is report-only).\n * @returns the health verdict, with the auto-heal outcome folded in.\n */\nexport function evaluateHealth(): HelmdHealth {\n  const first = evaluateHealthCore()\n  if (!HEALABLE.has(first.status)) return first\n  const policy = healPolicy()\n  if (!shouldRepair(first.status, policy)) {\n    first.autoHeal = reportOnlyVerdict(first.status, policy)\n    return first\n  }\n  const outcome = autoHealPreset()\n  if (!outcome.healed) {\n    first.autoHeal = outcome.verdict\n    return first\n  }\n  const healed = evaluateHealthCore()\n  healed.autoHeal = `healed (${first.status} → ${healed.status}) — ${artifactVerdict(healed)}; ${outcome.verdict}`\n  return healed\n}\n\n/**\n * Bundle row apply. Evaluates health once per boot and exposes it over HTTP.\n * @param ctx - the host composition context this row was plugged into.\n */\nexport function apply(ctx: Context, config?: unknown): void {\n  // Boot-time settings merge: the composition row's Config (edited in the DSH\n  // settings page) wins over the workbench-edited settings.json until the next\n  // workbench save. Absent config (row without a config section) keeps the file.\n  if (config !== undefined && config !== null && typeof config === 'object') {\n    try { saveSettings(config) } catch { /* settings must never block boot */ }\n  }\n  // tools 必须在列：api-routes 的 /api/helmd/tools 读 ctx.tools，cordis 的注入守卫\n  // 会对未声明的服务抛 `cannot get property \"tools\" without inject`（路由处理器\n  // 接住后对外表现为 HTTP 500）。\n  ctx.inject(['webServer', 'tools'], (webCtx) => {\n    try {\n      // Once per boot — the standing-mount semantics make boot the only\n      // moment this verdict is true (see module comment).\n      const health = evaluateHealth()\n      registerHelmdApi(webCtx, () => health)\n    } catch (e) {\n      console.error(`[helmd-health] webServer route registration failed: ${String((e as Error)?.message ?? e)}`)\n    }\n  })\n}\n"
    },
